// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.connectivity.contactimport android.content.Contextimport android.database.ContentObserverimport android.net.Uriimport android.os.Handlerimport android.os.Looperimport android.provider.ContactsContractimport androidx.work.OneTimeWorkRequestBuilderimport androidx.work.WorkManagerimport androidx.work.workDataOfimport timber.log.Timber/** * NOUS — Contact ContentObserver (Module 11 v3 — P1). * * Strategy §"ContactSearcher": "Add a ContentObserver on ContactsContract.Contacts.CONTENT_URI * that triggers a sync work (WorkManager OneTimeWorkRequest) to refresh the FTS mirror." * * Listens for system contacts changes (add / delete / update) and enqueues * a [ContactFtsSyncWorker] to rebuild the FTS4 mirror so searches stay fresh. * * ## Registration * * Must be registered dynamically (not in manifest) via * `context.contentResolver.registerContentObserver(...)`. [register] handles * this; [unregister] reverses it. The Hilt module creates a singleton and * registers at app startup. * * ## Debouncing * * The contacts provider can fire multiple notifications per second during * a bulk sync. We debounce via WorkManager's `ExistingWorkPolicy.KEEP` — * only one sync runs at a time, additional notifications are coalesced. */class ContactObserver(    private val context: Context,    private val handler: Handler = Handler(Looper.getMainLooper()),) : ContentObserver(handler) {    private var registered = false    /**     * Register the observer on the system Contacts provider.     *     * Idempotent — calling twice is a no-op.     */    fun register() {        if (registered) return        try {            context.contentResolver.registerContentObserver(                ContactsContract.Contacts.CONTENT_URI,                /* notifyForDescendants = */ true,                this,            )            registered = true            Timber.tag(TAG).i("Registered on ContactsContract.Contacts.CONTENT_URI.")        } catch (t: Throwable) {            Timber.tag(TAG).e(t, "register failed")        }    }    /** Unregister the observer. */    fun unregister() {        if (!registered) return        try {            context.contentResolver.unregisterContentObserver(this)            registered = false            Timber.tag(TAG).i("Unregistered.")        } catch (t: Throwable) {            Timber.tag(TAG).e(t, "unregister failed")        }    }    override fun onChange(selfChange: Boolean, uri: Uri?) {        super.onChange(selfChange, uri)        Timber.tag(TAG).d("Contacts changed (uri=$uri) — enqueuing FTS sync work.")        try {            val request = OneTimeWorkRequestBuilder<ContactFtsSyncWorker>()                .setInputData(workDataOf(ContactFtsSyncWorker.KEY_TRIGGER_URI to (uri?.toString() ?: "")))                .build()            WorkManager.getInstance(context).enqueueUniqueWork(                ContactFtsSyncWorker.UNIQUE_WORK_NAME,                androidx.work.ExistingWorkPolicy.KEEP,                request,            )        } catch (t: Throwable) {            Timber.tag(TAG).e(t, "Failed to enqueue ContactFtsSyncWorker")        }    }    private companion object {        private const val TAG = "ContactObserver"    }}